package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class CoordinateGridTest {
 static int[] points(String prompt){Matcher m=Pattern.compile("A\\((-?[0-9]+), (-?[0-9]+)\\), B\\((-?[0-9]+), (-?[0-9]+)\\)").matcher(prompt);assertTrue(m.find());return new int[]{Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3)),Integer.parseInt(m.group(4))};}
 @Test public void hundredPublicMidpointsByWalkingFromBothEnds(){Generator g=new Generator(new Random(740));Set<String> seen=new HashSet<>();for(int i=0;i<100;i++){Question q=g.next(CoordinateGrid.MID,seen,false);assertTrue(seen.add(q.signature()));int[] a=points(q.prompt);int x=a[0],y=a[1],otherX=a[2],otherY=a[3];while(x!=otherX){x+=Integer.signum(otherX-x);otherX-=Integer.signum(otherX-x);}while(y!=otherY){y+=Integer.signum(otherY-y);otherY-=Integer.signum(otherY-y);}assertTrue(new Checker().check(q,List.of(),List.of(""+x,""+y)).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+(x+1),""+y)).correct());assertEquals(4,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertEquals(7,q.diagram.values.length);}}
 @Test public void hundredDistancesUsingGridOrGivenReference(){Generator g=new Generator(new Random(741));Set<String> seen=new HashSet<>();Set<String> modes=new HashSet<>();Set<Integer> positions=new HashSet<>();for(int i=0;i<100;i++){Question q=g.next(CoordinateGrid.DIST,seen,true);assertTrue(seen.add(q.signature()));int[] a=points(q.prompt);int horizontal=Math.abs(a[2]-a[0]),vertical=Math.abs(a[3]-a[1]),length;if(q.prompt.contains("기준 선분")){assertEquals(0,horizontal%3);assertEquals(horizontal/3,vertical/4);length=5*(horizontal/3);modes.add("reference");}else{assertTrue(horizontal==0||vertical==0);length=horizontal+vertical;modes.add(horizontal==0?"vertical":"horizontal");}assertTrue(new Checker().check(q,List.of(),List.of(""+length)).correct());assertEquals(2,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertEquals(4,new HashSet<>(q.choices).size());assertEquals(""+length,q.choices.get(q.correctChoice));positions.add(q.correctChoice);}assertEquals(Set.of("reference","vertical","horizontal"),modes);assertEquals(Set.of(0,1,2,3),positions);}
 @Test public void boundedPublicGeometryAndReferenceStayIndependentOfAnswer(){Random r=new Random(742);for(String id:List.of(CoordinateGrid.MID,CoordinateGrid.DIST))for(int i=0;i<3000;i++){Question q=CoordinateGrid.create(Catalog.get(id),r);int[] a=points(q.prompt);for(int v:a)assertTrue(v>=-8&&v<=8);assertFalse(a[0]==a[2]&&a[1]==a[3]);for(int k=0;k<4;k++)assertEquals(a[k],q.diagram.values[k],0);if(id.equals(CoordinateGrid.MID)){assertEquals(0,(a[2]-a[0])%2);assertEquals(0,(a[3]-a[1])%2);}else if(q.prompt.contains("기준 선분")){assertEquals(5*Math.abs(a[2]-a[0])/3,Math.hypot(a[2]-a[0],a[3]-a[1]),1e-9);assertArrayEquals(new double[]{3,4,5},Arrays.copyOfRange(q.diagram.values,4,7),0);}Arrays.fill(q.answers,"999");assertEquals(a[0],q.diagram.values[0],0);}}
}
